        }
        return String.valueOf(ans).substring(0, Math.max(ans.length() - 1, 0));
    }

    private static String[] getSorted(int[] a) {
        List<Integer> al = new ArrayList<>();
        for (int i : a) al.add(i);
        al.sort(null);
        String[] as = new String[al.size()];
        for (int i = 0; i < as.length; ++i) as[i] = String.valueOf(al.get(i));
        return as;
    }
